"""Original Native two-truck following episode with four synchronized views."""
import argparse,hashlib,json,queue,subprocess,traceback,xml.etree.ElementTree as ET
from pathlib import Path
from worker_exchange.native_output import FrameMap
from worker_exchange.media import compose_four_views
from worker_exchange.world_restore import snapshot,restore
ROOT=Path(__file__).resolve().parent

def check():
 cfg=json.loads((ROOT/'config.json').read_text());road=ET.parse(ROOT/'scene.xodr').getroot().find("road[@id='1']")
 assert road is not None and float(road.get('length'))>=1500
 assert len(road.findall('.//lane[@type="driving"]'))==2
 assert cfg['duration_s']==42 and cfg['rate_hz']==20
 assert [(c['name'],c['width'],c['height']) for c in cfg['cameras']]==[('overview',1920,1080),('approach',1280,720),('reference_corner',1280,720),('driver_reference',1280,720)]
 assert cfg['required_atoms']==['kin.speed']
 return {'passed':True,'two_opposed_driving_lanes':True,'carla_contacted':False}

def state(actor):
 t=actor.get_transform();v=actor.get_velocity();c=actor.get_control()
 return {'actor_id':actor.id,'position_m':[t.location.x,t.location.y,t.location.z],
  'velocity_mps':[v.x,v.y,v.z],'body_vertices_m':[[p.x,p.y,p.z] for p in actor.bounding_box.get_world_vertices(t)],
  'applied_control':{'throttle':c.throttle,'brake':c.brake}}

def run(args):
 import carla
 from pipeline_capture import PipelineCapture
 from following_controller import FollowingController,leader_requested_speed
 from analyze import finalize
 cfg=json.loads((ROOT/'config.json').read_text());out=Path(args.output_dir)
 client=carla.Client(args.host,args.port);client.set_timeout(90);saved=snapshot(client)
 owned=[];encoders={};streams={};queues={};cameras={};capture=None;frames=0;errors=[];road_name=None
 try:
  world=client.generate_opendrive_world((ROOT/'scene.xodr').read_text())
  settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05;world.apply_settings(settings)
  world.set_weather(carla.WeatherParameters.ClearNoon);road_name=world.get_map().name
  bp=world.get_blueprint_library().find(cfg['truck_blueprint'])
  bp.set_attribute('role_name','subject_heavy_truck');wp=world.get_map().get_waypoint_xodr(1,-1,300)
  ego=world.spawn_actor(bp,wp.transform);owned.append(ego)
  bp2=world.get_blueprint_library().find(cfg['truck_blueprint']);bp2.set_attribute('role_name','leading_heavy_truck')
  wp2=world.get_map().get_waypoint_xodr(1,-1,460);lead=world.spawn_actor(bp2,wp2.transform);owned.append(lead)
  for truck in (ego,lead):truck.apply_control(carla.VehicleControl(brake=1,hand_brake=True))
  for _ in range(30):world.tick()
  contexts=[]
  for role,truck in [('ego',ego),('lead',lead)]:
   width=2*truck.bounding_box.extent.y;contexts.append({'role':role,'native_actor_id':truck.id,'blueprint':truck.type_id,'measured_bbox_width_m':width,'physical_width_at_least_80in':width>=2.032})
  if not all(t['physical_width_at_least_80in'] for t in contexts):raise ValueError('Truck blueprint physical width <80 inches')
  (out/'truck_context.json').write_text(json.dumps({'trucks':contexts,'same_direction_lane_count':1,
   'source':'Original Native bounding boxes and OpenDRIVE road1 lane inventory; physical interpretation pending'},indent=2)+'\n')
  for spec in cfg['cameras']:
   name,w,h=spec['name'],spec['width'],spec['height'];camera_bp=world.get_blueprint_library().find('sensor.camera.rgb')
   for key,value in [('image_size_x',w),('image_size_y',h),('fov',spec['fov_deg']),('sensor_tick',0)]:camera_bp.set_attribute(key,str(value))
   if name=='overview':pose=carla.Transform(carla.Location(x=0,y=0,z=100),carla.Rotation(pitch=-90));attach=ego
   elif name=='approach':pose=carla.Transform(carla.Location(x=-15,y=0,z=9),carla.Rotation(pitch=-12));attach=ego
   elif name=='reference_corner':pose=carla.Transform(carla.Location(x=0,y=-35,z=75),carla.Rotation(pitch=-75));attach=lead
   else:pose=carla.Transform(carla.Location(x=0,y=0,z=2.2),carla.Rotation());attach=ego
   camera=world.spawn_actor(camera_bp,pose,attach_to=attach);owned.append(camera);cameras[name]=camera;queues[name]=queue.Queue();camera.listen(queues[name].put)
   stream=(out/(name+'.encoder.log')).open('x');streams[name]=stream
   encoders[name]=subprocess.Popen(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n','-f','rawvideo','-pix_fmt','bgra','-s',f'{w}x{h}','-r','20','-i','pipe:0','-an','-c:v','ffv1','-pix_fmt','bgr0',str(out/(name+'.mkv'))],stdin=subprocess.PIPE,stderr=stream)
  capture=PipelineCapture(client,ego,out,cfg['selected_case_id'],required_observations=cfg['required_atoms'])
  start=world.get_snapshot().timestamp.elapsed_seconds;controller=FollowingController(cfg['requested_body_gap_m'])
  with FrameMap(out/'video_frames.jsonl') as fmap,(out/'truck_history.jsonl').open('x') as history:
   for i in range(cfg['duration_s']*20):
    before_ego,before_lead=state(ego),state(lead);now_before=i*.05
    requested=leader_requested_speed(now_before);lead_speed=lead.get_velocity().length()
    lead.apply_control(carla.VehicleControl(throttle=max(0,min(.6,.4*(requested-lead_speed))),brake=max(0,min(.6,.3*(lead_speed-requested)))))
    command=controller.step(i,now_before,before_ego,before_lead)
    ego.apply_control(carla.VehicleControl(throttle=command['throttle'],brake=command['brake'],hand_brake=command['hand_brake']))
    frame=world.tick();now=world.get_snapshot().timestamp.elapsed_seconds-start
    originals={}
    for spec in cfg['cameras']:
     name=spec['name'];image=queues[name].get(timeout=30)
     while image.frame<frame:image=queues[name].get(timeout=30)
     if image.frame!=frame:raise ValueError('Original camera tick mismatch: '+name)
     encoders[name].stdin.write(image.raw_data);originals[name]=hashlib.sha256(image.raw_data).hexdigest()
    current_ego,current_lead=state(ego),state(lead)
    history.write(json.dumps({'frame':frame,'time_s':now,'ego_vertices_m':current_ego['body_vertices_m'],
      'lead_vertices_m':current_lead['body_vertices_m'],'ego_actor_id':ego.id,'lead_actor_id':lead.id,
      'requested_controls':command,'original_camera_sha256':originals})+'\n')
    capture.capture(frame,now);fmap.append(frame,now);frames+=1
 except BaseException as error:errors.append({'message':str(error),'traceback':traceback.format_exc()})
 finally:
  if capture:
   try:capture.close(confirmed=not errors and frames==cfg['duration_s']*20)
   except BaseException as error:errors.append({'capture_close':str(error)})
  for process in encoders.values():
   try:
    process.stdin.close()
    if process.wait(timeout=180):errors.append({'encoder_exit':process.returncode})
   except BaseException as error:errors.append({'encoder':str(error)})
  for stream in streams.values():stream.close()
  for actor in reversed(owned):
   try:actor.destroy()
   except BaseException as error:errors.append({'destroy':str(error)})
  try:restoration=restore(client,saved)
  except BaseException as error:errors.append({'restore':str(error)});restoration={'restored':False}
  (out/'native-run-status.json').write_text(json.dumps({'frames':frames,'errors':errors,'restoration':restoration},indent=2)+'\n')
 if errors:raise RuntimeError('Native capture failed: '+str(errors))
 receipt=compose_four_views({name:out/(name+'.mkv') for name in cameras},out/'video_frames.jsonl',out/'raw.mkv')
 (out/'four-view-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
 finalize(out,out/'analysis-report.json')

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--output-dir',default='.')
 p.add_argument('--host',default='127.0.0.1');p.add_argument('--port',type=int,default=2000);a=p.parse_args()
 if a.check:print(json.dumps(check()))
 else:run(a)

"""Saved-only 500 ft truck gap and width evidence; no statutory verdict."""
import argparse, hashlib, json, math
from pathlib import Path
from worker_exchange.native_output import write_result
from following_controller import along_route_body_gap

def required(root,name):
    p=root/name
    if not p.is_file():raise ValueError('Missing required source: '+name)
    return p

def body_gap(root):
    rows=[json.loads(s) for s in required(root,'truck_history.jsonl').read_text().splitlines() if s]
    if not rows:raise ValueError('No full-body truck samples')
    gaps=[]
    for row in rows:
        ego,lead=row['ego_vertices_m'],row['lead_vertices_m']
        if len(ego)!=8 or len(lead)!=8:raise ValueError('Require all eight body vertices per truck')
        gap=along_route_body_gap(ego,lead)
        if not math.isfinite(gap):raise ValueError('Nonfinite truck body gap')
        gaps.append({'frame':row['frame'],'time_s':row['time_s'],'along_route_body_gap_m':gap})
    return {'samples':gaps,'minimum_m':min(r['along_route_body_gap_m'] for r in gaps),
            'maximum_m':max(r['along_route_body_gap_m'] for r in gaps),
            '500ft_m':152.4,'above_500ft_original_frames':[r['frame'] for r in gaps if r['along_route_body_gap_m']>=152.4],
            'sampling_limit':'Original 20 Hz full vertices projected to 3D crest centerline arc; between-frame gaps unverified'}

def truck_width_and_lanes(root):
    value=json.loads(required(root,'truck_context.json').read_text())
    if len(value.get('trucks',[]))!=2 or not value.get('same_direction_lane_count'):
        raise ValueError('Incomplete truck/lane context')
    return {'trucks':value['trucks'],'same_direction_lane_count':value['same_direction_lane_count'],
            '80in_m':2.032,'source':value['source'],'qualification_unconfirmed':True}

def finalize(root,output):
    cfg=json.loads(required(root,'config.json').read_text());gap=body_gap(root);context=truck_width_and_lanes(root)
    measurements={}
    for key,method,value,source in [('truck_body_gap','body_gap',gap,'truck_history.jsonl'),
                                     ('truck_width_and_lanes','truck_width_and_lanes',context,'truck_context.json')]:
        measurements[key]={'method':method,'value':value,'sources':{source:hashlib.sha256(required(root,source).read_bytes()).hexdigest()}}
    output.write_text(json.dumps({'format':'worker-analysis-report-v1','case_id':cfg['selected_case_id'],'measurements':measurements,
      'limitations':['Fixture is diagnostic only.','Truck width, route, overtaking opportunity and 500 ft space require Native and legal review.']},indent=2)+'\n')
    rows=[json.loads(s) for s in required(root,'trace.jsonl').read_text().splitlines() if s]
    channels=root/'channels';channels.mkdir(exist_ok=True)
    (channels/'kin.speed.jsonl').write_text(''.join(json.dumps({'time_s':r['time_s'],'value':r['speed_mps']})+'\n' for r in rows))
    target=cfg['case']['variable_assignments']['requested_body_gap_m']['value']
    result={'case_id':cfg['selected_case_id'],'measured_values':{'minimum_body_gap_m':gap['minimum_m']},
      'target_checks':[{'target':'observed_body_gap_m','requested':target,'measured':gap['minimum_m'],'method':'full-body extrema along directed road',
        'tolerance':20,'matched':abs(gap['minimum_m']-target)<=20,'physical_cause_confirmed':False,'cause_evidence':'truck_history.jsonl'}],
      'setup_confirmed':False,'behavior_attempted':True,'maneuver_completed':False,'termination_reason':'saved diagnostic only',
      'physical_failure_flags':{'detection_validated':False},'trace_reference':'trace.jsonl','video_references':['raw.mkv'],
      'video_frame_map_reference':'video_frames.jsonl','recording_description':cfg['case']['recording_description'],
      'recording_evidence':[{'name':'kin.speed','unit':'m/s','reference':'channels/kin.speed.jsonl'}], 'realized_observables':{}}
    write_result(root,result)

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--attempt',required=True);p.add_argument('--output',required=True)
 a=p.parse_args();finalize(Path(a.attempt),Path(a.output))

"""Prospective observed-state feedback for the unchanged C104496 crest.
No CARLA import, driving, legal threshold, or native feasibility claim.
The native caller must supply fresh synchronized actor state on every tick.
"""
import math
from dataclasses import dataclass

DT = 0.05
CREST = 750.0
ROUTE_LENGTH = 1500.0


def elevation(station):
    if station < 650.0:
        return -4.0 + 0.08 * (station - 650.0)
    if station > 850.0:
        return -4.0 - 0.08 * (station - 850.0)
    return -0.0004 * (station - CREST) ** 2


def grade(station):
    return 0.08 if station < 650.0 else -0.08 if station > 850.0 else -0.0008 * (station - CREST)


def _primitive(u):
    return 0.5 * (u * math.sqrt(1.0 + u * u) + math.asinh(u))


def route_distance(station):
    """3D centreline arc length from x=0; native x is OpenDRIVE station here."""
    if not 0.0 <= station <= ROUTE_LENGTH:
        raise ValueError('Body outside supported centreline; do not extrapolate')
    slope_scale = math.sqrt(1.0 + 0.08 ** 2)
    if station <= 650.0:
        return station * slope_scale
    crest_part = (_primitive(0.08) - _primitive(-0.0008 * (min(station, 850.0) - CREST))) / 0.0008
    return 650.0 * slope_scale + crest_part + max(0.0, station - 850.0) * slope_scale


def body_references(vertices):
    if len(vertices) != 8 or any(len(v) != 3 for v in vertices):
        raise ValueError('Require all eight actual native world-space box vertices')
    values = [route_distance(float(v[0])) for v in vertices]
    return {'rear_route_m': min(values), 'front_route_m': max(values),
            'convention': 'Extrema of all eight native body vertices projected by world x onto the unchanged straight 3D centreline; not native component gap'}


def along_route_body_gap(ego_vertices, leader_vertices):
    a, b = body_references(ego_vertices), body_references(leader_vertices)
    return b['rear_route_m'] - a['front_route_m']


def tangent_speed(position, velocity):
    g = grade(float(position[0]))
    return (float(velocity[0]) + g * float(velocity[2])) / math.sqrt(1.0 + g * g)


def leader_requested_speed(time_s):
    # Engineering profile for coverage only; all observed histories remain mandatory.
    if time_s < 2.0 or time_s >= 34.0:
        return 0.0
    if time_s < 22.0 or time_s >= 28.0:
        return 9.0
    return 6.0


def _clamp(value, lower, upper):
    return max(lower, min(upper, value))


@dataclass
class FollowingController:
    target_body_gap_m: float
    last_frame: int = -1
    integral_speed_error: float = 0.0

    def step(self, frame, time_s, ego, leader):
        """Consume actual pre-control states, never an authored leader trajectory.
        State keys: actor_id, body_vertices_m, position_m, velocity_mps.
        Returns requests and the complete inputs used, for same-episode retention.
        """
        if not 120.0 <= self.target_body_gap_m <= 180.0:
            raise ValueError('Unselected prospective physical gap')
        if frame <= self.last_frame or ego['actor_id'] == leader['actor_id']:
            raise ValueError('Require a fresh synchronized frame and distinct actors')
        if not math.isfinite(time_s):
            raise ValueError('Require native elapsed time')
        observed_gap = along_route_body_gap(ego['body_vertices_m'], leader['body_vertices_m'])
        ego_speed = tangent_speed(ego['position_m'], ego['velocity_mps'])
        leader_speed = tangent_speed(leader['position_m'], leader['velocity_mps'])
        gap_error = observed_gap - self.target_body_gap_m
        # Position and relative-speed feedback: stopping/changes emerge from leader state.
        requested_speed = _clamp(leader_speed + 0.65 * gap_error + 0.50 * (leader_speed - ego_speed), 0.0, 17.0)
        error = requested_speed - ego_speed
        trial = _clamp(self.integral_speed_error + DT * error, -5.0, 5.0)
        observed_leader_control = leader['applied_control']
        feedforward = float(observed_leader_control['throttle']) - float(observed_leader_control['brake'])
        output = feedforward + 0.6 * error + 0.15 * trial
        if not ((output >= 1.0 and error > 0.0) or (output <= -1.0 and error < 0.0)):
            self.integral_speed_error = trial
        output = feedforward + 0.6 * error + 0.15 * self.integral_speed_error
        self.last_frame = frame
        stopped_leader_closure = abs(leader_speed) < 0.1 and gap_error <= 0.3
        return {
            'throttle': 0.0 if stopped_leader_closure else _clamp(output, 0.0, 1.0), 'brake': 0.7 if stopped_leader_closure else _clamp(-output, 0.0, 1.0),
            'hand_brake': (stopped_leader_closure or requested_speed < 0.02) and abs(ego_speed) < 0.05,
            'requested_ego_speed_mps': requested_speed,
            'actual_controller_inputs': {'frame': frame, 'time_s': time_s,
                'ego_actor_id': ego['actor_id'], 'leader_actor_id': leader['actor_id'],
                'ego_state': ego, 'leader_state': leader,
                'observed_along_route_body_gap_m': observed_gap, 'target_body_gap_m': self.target_body_gap_m,
                'ego_tangent_speed_mps': ego_speed, 'leader_tangent_speed_mps': leader_speed,
                'relative_tangent_speed_mps': leader_speed - ego_speed,
                'observed_leader_control_feedforward':feedforward,
                'integral_speed_error': self.integral_speed_error},
            'limitations': 'Prospective longitudinal control only; native route steering, body clearance, grade response, braking and measurement support require independent native checks.'}

